fun onEvent(e: Event) {
    watermark = maxOf(watermark, e.eventTime)
    val start = e.eventTime - e.eventTime % size
    if (start + size + grace <= watermark) {      // its window already closed
        lateDropped++
        return
    }
    open.merge(start to e.key, 1, Int::plus)
    while (open.isNotEmpty() && open.firstKey().first + size + grace <= watermark) {
        val (k, count) = open.pollFirstEntry()
        emit(k.second, k.first, count)           // final, once
    }
}
// event at 59 s, watermark 69 s: window 0-60 closes at 60 + 10 = 70 > 69, so it is counted.
// watermark 70 s: 70 >= 70, the window is closed and its count already emitted: dropped as late.
